using UnityEngine;
using Flynn.Events;

// 2.5D force-based character controller. Moves on the XZ plane via acceleration
// toward a target velocity, so Unity physics drives interactions: PhysicMaterial
// friction (ice/mud), Rigidbody.drag (water), and AddForce zones (wind) all
// compose naturally instead of being overwritten. Small jump impulse, gravity
// handled by the Rigidbody.
[RequireComponent(typeof(Rigidbody))]
public class SolarpunkCharacterController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;        // target horizontal speed under input
    [SerializeField] private float acceleration = 40f;    // how hard we drive toward target
    [SerializeField] private float jumpForce = 6f;
    // Baseline drag is 0: accel-to-target already arrests horizontal motion when input is
    // released (target velocity 0 -> decel force), so we need no passive drag — and drag is
    // isotropic, which would damp jump/fall. Water zones raise this temporarily; ice keeps it low.
    [SerializeField] private float groundDrag = 0f;
    [SerializeField] private float groundCheckDistance = 0.12f;
    [SerializeField] private LayerMask groundLayers = ~0;
    // Ice low-grip is re-asserted by the zone every physics step. Latch it for a short grace
    // window so a single missed OnTriggerStay (e.g. player center crossing the trigger edge
    // while the capsule is still on the ice) doesn't snap the ground brake back on for a step
    // and bleed the slide. Grace ends well before the player is truly off the ice.
    [SerializeField] private float lowGripGrace = 0.2f;

    public Vector3 MoveInput => moveInput;
    public bool IsGrounded => isGrounded;
    /// <summary>Horizontal speed normalized 0-1 relative to moveSpeed.</summary>
    public float NormalizedSpeed => rb != null
        ? Mathf.Clamp01(new Vector2(rb.velocity.x, rb.velocity.z).magnitude / moveSpeed)
        : 0f;

    /// <summary>Multiplies steering force each physics step. Ice sets this low (slidey, weak
    /// steering, momentum dominates) — kept &gt;0 so the player can always escape ice. Auto-resets to 1.</summary>
    public float SteeringControl { get; set; } = 1f;

    /// <summary>Multiplies the target move speed each physics step. Water/Mud set this below 1 to
    /// slow the player noticeably (lowering the target, since drag/friction barely dents accel-to-target).
    /// Auto-resets to 1.</summary>
    public float SpeedMultiplier { get; set; } = 1f;

    /// <summary>Set false each physics step by a mud zone while grounded on it: blocks jumping
    /// ("mud stops vertical movement"). Auto-resets to true.</summary>
    public bool CanJump { get; set; } = true;

    /// <summary>Set true each physics step by an ice zone: the controller stops braking toward
    /// zero when there's no input, so momentum carries (glide). Steering still applies (scaled by
    /// SteeringControl) so the player can nudge off the ice. Auto-resets to false.</summary>
    public bool LowGrip { get; set; } = false;

    public Vector3 RbVelocityDirection { get; private set; }

    private Rigidbody rb;
    private Collider bodyCollider;
    private bool isGrounded;
    private bool wasGrounded;
    private Vector3 moveInput;
    private bool jumpQueued;
    private float lowGripTimer;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        bodyCollider = GetComponent<Collider>();
        rb.drag = groundDrag;
        rb.freezeRotation = true;
    }

    private void Update()
    {
        moveInput.x = Input.GetAxisRaw("Horizontal");
        moveInput.z = Input.GetAxisRaw("Vertical");
        RbVelocityDirection = rb.velocity.normalized;
        if (moveInput.sqrMagnitude > 1f) moveInput.Normalize();

        if (Input.GetButtonDown("Jump")) jumpQueued = true;
    }



    private void FixedUpdate()
    {
        UpdateGrounded();

        // Accelerate toward the input-driven target velocity (XZ only). External forces
        // (wind AddForce) and surface friction are left to the solver. SpeedMultiplier
        // lowers the target (water/mud slow); SteeringControl scales the force (ice = slidey,
        // weak steering so momentum carries, but never 0 so the player can't get stuck).
        Vector3 horizVel = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
        Vector3 inputDir = new Vector3(moveInput.x, 0f, moveInput.z);
        bool idle = inputDir.sqrMagnitude < 0.01f;
        // Latch low-grip: refresh the timer while the zone asserts it, otherwise decay it.
        // The brake stays off for the whole grace window, surviving single-step trigger gaps.
        if (LowGrip) lowGripTimer = lowGripGrace;
        else lowGripTimer -= Time.fixedDeltaTime;
        bool lowGrip = lowGripTimer > 0f;
        if (lowGrip)
        {
            // Ice: momentum carries, input only steers. With input, push in the input direction
            // WITHOUT the "- horizVel" brake term (that term is what kills the slide on normal
            // ground), so existing momentum is preserved and the velocity vector rotates toward
            // the input instead of being reset to it. Speed is capped to moveSpeed so the additive
            // force can't run away. Idle = no force, the frictionless surface keeps the glide.
            if (!idle)
            {
                rb.AddForce(inputDir * moveSpeed * acceleration * SteeringControl, ForceMode.Acceleration);
                Vector3 hv = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
                float maxSpeed = moveSpeed * SpeedMultiplier;
                if (hv.magnitude > maxSpeed)
                {
                    hv = hv.normalized * maxSpeed;
                    rb.velocity = new Vector3(hv.x, rb.velocity.y, hv.z);
                }
            }
        }
        else
        {
            // Normal ground: accelerate toward the input-driven target velocity (XZ only).
            // SpeedMultiplier lowers the target (water/mud slow); SteeringControl scales the
            // force (wind = weak self-correction so wind blows you).
            Vector3 targetVel = inputDir * moveSpeed * SpeedMultiplier;
            Vector3 dv = targetVel - horizVel;
            rb.AddForce(dv * acceleration * SteeringControl, ForceMode.Acceleration);
        }

        if (jumpQueued && isGrounded && CanJump)
        {
            Vector3 v = rb.velocity; v.y = 0f; rb.velocity = v;
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
            isGrounded = false;
            PublishEvent(new PlayerJumped(transform.position));
        }
        jumpQueued = false;

        // Per-step terrain modifiers; zones re-assert them in OnTriggerStay (which fires
        // after FixedUpdate within the same physics step).
        SteeringControl = 1f;
        SpeedMultiplier = 1f;
        CanJump = true;
        LowGrip = false;

        // Detect landing (was airborne, now grounded).
        if (!wasGrounded && isGrounded)
            PublishEvent(new PlayerLanded(transform.position));
        wasGrounded = isGrounded;
    }

    private void UpdateGrounded()
    {
        if (bodyCollider == null)
        {
            isGrounded = false;
            return;
        }

        Vector3 origin = bodyCollider.bounds.center;
        origin.y = bodyCollider.bounds.min.y + 0.02f;

        isGrounded = Physics.Raycast(
            origin,
            Vector3.down,
            groundCheckDistance,
            groundLayers,
            QueryTriggerInteraction.Ignore
        );
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        // Ground check ray
        if (bodyCollider != null)
        {
            Vector3 origin = bodyCollider.bounds.center;
            origin.y = bodyCollider.bounds.min.y + 0.02f;
            Debug.DrawLine(origin, origin + Vector3.down * groundCheckDistance,
                isGrounded ? Color.green : Color.red);
        }

        // Velocity vector
        if (rb != null)
        {
            Debug.DrawRay(transform.position, rb.velocity, Color.cyan);
        }
    }
#endif
}

using UnityEngine;

/// <summary>
/// Reads SolarpunkCharacterController state and feeds the Animator. Locomotion is now a
/// velocity blend tree: this just pushes VelocityX/Y/Z (Rigidbody velocity) plus Speed and
/// IsGrounded; the tree owns direction/clip selection. Also owns the wrench swing phase
/// (windup freeze / release scale on animator.speed) and exposes the IPlayerVisual surface
/// (VisualCenter, attack/charge) for the combat & interaction controllers.
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class FlynnAnimationDriver : MonoBehaviour, IPlayerVisual
{
    [SerializeField] private SolarpunkCharacterController _controller;
    [SerializeField] private Camera _camera;
    [Tooltip("Assign the child Visual GameObject that holds the SpriteRenderer. Only this object will billboard — the physics root stays unrotated.")]
    [SerializeField] private Transform _visualRoot;
    [SerializeField, Range(0.1f, 5f)] private float _visualScale = 1f;

    [Header("Direction views")]
    [Tooltip("Direction view GameObjects under New_Visual. Auto-found by name at Awake if left empty.")]
    [SerializeField] private GameObject _viewFront;
    [SerializeField] private GameObject _viewBack;
    [SerializeField] private GameObject _viewSide;
    [SerializeField] private GameObject _viewLeftBack;
    [SerializeField] private GameObject _viewLeftDown;

    [Header("Facing (sprite flip)")]
    [Tooltip("SpriteRenderer to flip. Auto-found on _visualRoot at Awake if left empty.")]
    [SerializeField] private SpriteRenderer _sprite;
    [Tooltip("Min horizontal speed before facing updates. Below this the last facing is held (no flip flicker when idling).")]
    [SerializeField, Range(0f, 1f)] private float _faceDeadzone = 0.05f;

    [Header("Petal (procedural)")]
    [Tooltip("The petal transform. Dynamically reparented to the active view's Head/PetalPivot at runtime.")]
    [SerializeField] private Transform _petal;
    [Tooltip("How fast the bounce oscillation runs (cycles per second).")]
    [SerializeField, Range(1f, 20f)] private float _petalBounceSpeed = 8f;
    [Tooltip("Max scale-Y added to the petal at full speed (pivot is on the bottom).")]
    [SerializeField, Range(0f, 0.5f)] private float _petalBounceAmplitude = 0.15f;
    [Tooltip("Max Z-rotation degrees the petal leans towards movement direction.")]
    [SerializeField, Range(0f, 45f)] private float _petalMaxLeanDeg = 20f;
    [Tooltip("How quickly the petal follows the target lean angle (higher = snappier).")]
    [SerializeField, Range(1f, 30f)] private float _petalLeanLerpSpeed = 8f;
    [Tooltip("Max lean angle clamped so the petal never goes fully sideways (degrees).")]
    [SerializeField, Range(0f, 90f)] private float _petalSidewaysClampDeg = 10f;

    [Header("Head bob (procedural)")]
    [Tooltip("Bob oscillation speed (cycles per second at full run speed).")]
    [SerializeField, Range(1f, 20f)] private float _headBobSpeed = 11f;
    [Tooltip("Max vertical offset (world units) at full speed.")]
    [SerializeField, Range(0f, 0.15f)] private float _headBobHeight = 0.04f;
    [Tooltip("Max horizontal sway offset (world units) — creates the figure-8 feel.")]
    [SerializeField, Range(0f, 0.1f)] private float _headBobSway = 0.015f;
    [Tooltip("Max Z-rotation wiggle (degrees) at full speed.")]
    [SerializeField, Range(0f, 15f)] private float _headBobTiltDeg = 5f;

    [Header("Limb walk cycle (procedural)")]
    [Tooltip("Walk cycle speed (cycles per second at full run). Synced with head bob by default.")]
    [SerializeField, Range(1f, 20f)] private float _limbCycleSpeed = 11f;
    [Tooltip("Max rotation degrees for feet during swing.")]
    [SerializeField, Range(0f, 45f)] private float _footTiltDeg = 25f;
    [Tooltip("Max rotation degrees for arms during swing. Arms swing opposite to same-side foot.")]
    [SerializeField, Range(0f, 45f)] private float _armTiltDeg = 20f;

    [Header("Visual Center (for throw origin & aim reticle)")]
    [Tooltip("Half the sprite's visible height in world units. Used to compute the billboard's visual centre for camera-corrected spawn/reticle positions.")]
    [SerializeField, Range(0f, 3f)] private float _spriteHalfHeight = 0.5f;

    /// <summary>
    /// World-space centre of the billboarded sprite, accounting for camera tilt.
    /// Because the billboard's up = camera.up (not world up), the visual centre
    /// shifts horizontally toward the viewer on a tilted perspective camera.
    /// Use this for spawn points and any indicator that should appear to originate
    /// from the sprite rather than from the physics root (feet position).
    /// </summary>
    public Vector3 VisualCenter =>
        _visualRoot != null
            ? _visualRoot.position + _visualRoot.up * _spriteHalfHeight
            : transform.position;

    /// <summary>
    /// XZ projection of VisualCenter at the character's foot Y.
    /// Use this for ground-plane indicators (aim reticle root, shadow) so they
    /// appear centred under the sprite rather than under the physics root.
    /// </summary>
    public Vector3 VisualGroundCenter =>
        new Vector3(VisualCenter.x, transform.position.y, VisualCenter.z);

    private Animator _animator;

    // Last pressed XZ facing direction, held while idle so the blend tree doesn't snap back to
    // the front/Down pose on release. Starts facing front (Down = -Z).
    private Vector2 _lastFacingXZ = new Vector2(0f, -1f);

    // ── Swing (wrench) phase ────────────────────────────────────────────────────
    // The charge windup freezes the attack clip on frame 0; the release plays it at a
    // charge-scaled speed. These own animator.speed while active so the locomotion speed
    // logic in Update doesn't stomp the freeze/scale.
    private enum SwingPhase { None, Charging, Releasing }
    private SwingPhase _swingPhase = SwingPhase.None;
    private int _swingIndex;
    private float _attackSpeed = 1f;
    private bool _releaseSeen; // saw the attack state begin after a release (Play settles a frame late)

    private const float AttackFps = 12f; // matches FlynnAnimationSetup.Fps — used to map charge → windup frame
    private const int WindupStartFrame = 1;
    private const int WindupEndFrame   = 5;

    // attackIndex → last-frame index of that attack clip (length*frameRate). Cached at Awake so
    // the windup scrub is exact and never depends on a fragile per-frame state-length read.
    private readonly System.Collections.Generic.Dictionary<int, float> _attackLastFrame
        = new System.Collections.Generic.Dictionary<int, float>();

    // Animator AttackIndex (1-4) → attack state name. Matches FlynnAnimationSetup.
    private static string AttackStateName(int animIndex) => animIndex switch
    {
        1 => "Attack_Pick",
        2 => "Attack_Axe",
        3 => "Attack_Hammer",
        _ => "Attack_Wrench",
    };

    private static readonly int SpeedHash       = Animator.StringToHash("Speed");
    private static readonly int IsGroundedHash  = Animator.StringToHash("IsGrounded");
    private static readonly int AttackHash      = Animator.StringToHash("Attack");
    private static readonly int AttackIndexHash = Animator.StringToHash("AttackIndex");

    private static readonly int xVelocityHash = Animator.StringToHash("VelocityX");
    private static readonly int yVelocityHash = Animator.StringToHash("VelocityY");
    private static readonly int zVelocityHash = Animator.StringToHash("VelocityZ");

    // ── Public API ────────────────────────────────────────────────────────────

    /// <summary>
    /// Fires the correct attack animation. animIndex: 1=pick 2=axe 3=hammer 4=wrench.
    /// Called by the wrench controllers; safe to call from any other system.
    ///
    /// Guard: discards the request while any attack state is already active.
    /// Attack states must carry the "Attack" tag in the Animator Controller for this
    /// guard to work. Without it, the Any State trigger queues up and double-fires
    /// when the animation exits back to idle.
    /// </summary>
    public void TriggerAttack(int animIndex)
    {
        if (_animator == null) return;
        if (IsAttacking) return;
        _animator.SetInteger(AttackIndexHash, animIndex);
        _animator.SetTrigger(AttackHash);
    }

    /// <summary>
    /// Enter the swing windup: jump the matching attack clip to its start frame and pause it.
    /// Bypasses the AnyState "Attack" trigger (so it never double-fires); the release resumes
    /// the same state from wherever the windup paused. Pass the tool's Animator AttackIndex (1-4).
    /// </summary>
    public void BeginChargePose(int animIndex)
    {
        if (_animator == null) return;
        _swingPhase = SwingPhase.Charging;
        _swingIndex = animIndex;
        _animator.Play(AttackStateName(animIndex), 0, 0f);
        _animator.speed = 0f; // paused; UpdateChargePose drives the frame from charge
    }

    /// <summary>
    /// Drive the (paused) windup pose: the clip scrubs from frame 1 → 5 as <paramref name="charge01"/>
    /// goes 0 → 1 and holds at frame 5, so the buildup visibly winds up. Also live-swaps the tool.
    /// </summary>
    public void UpdateChargePose(int animIndex, float charge01)
    {
        return; // TODO
        if (_animator == null || _swingPhase != SwingPhase.Charging) return;
        _swingIndex = animIndex;
        _animator.Play(AttackStateName(animIndex), 0, WindupNormalizedTime(animIndex, charge01));
        _animator.speed = 0f; // paused at the scrubbed frame
    }

    /// <summary>
    /// Charge fraction → clip normalizedTime sitting on a discrete windup frame. Charge 0→1 steps
    /// the displayed frame 1,2,3,4,5 (rounded), holding on frame 5 at full charge.
    /// </summary>
    private float WindupNormalizedTime(int animIndex, float charge01)
    {
        // Last-frame index of this clip (cached). Fallback to a live read if not cached yet.
        if (!_attackLastFrame.TryGetValue(animIndex, out float lastFrame))
        {
            lastFrame = _animator.GetCurrentAnimatorStateInfo(0).length * AttackFps;
            if (lastFrame < 1f) return 0f;
        }
        int frame = Mathf.RoundToInt(Mathf.Lerp(WindupStartFrame, WindupEndFrame, Mathf.Clamp01(charge01)));
        return Mathf.Clamp01(frame / lastFrame);
    }

    /// <summary>
    /// Release the swing: play the attack clip from frame 0 at <paramref name="animSpeed"/>
    /// (lower = heavier/slower). Hands control back to locomotion when the clip exits.
    /// </summary>
    public void ReleaseSwing(int animIndex, float animSpeed)
    {
        if (_animator == null) return;
        if (animIndex != _swingIndex || _swingPhase != SwingPhase.Charging)
        {
            _swingIndex = animIndex;
            _animator.Play(AttackStateName(animIndex), 0, 0f);
        }
        _attackSpeed = Mathf.Max(0.05f, animSpeed);
        _swingPhase = SwingPhase.Releasing;
        _releaseSeen = false;
    }

    /// <summary>Abort a windup (e.g. wrench unequipped / throw started) and return to idle.</summary>
    public void CancelSwing()
    {
        if (_animator == null) { _swingPhase = SwingPhase.None; return; }
        _swingPhase = SwingPhase.None;
        _animator.speed = 1f;
        _animator.Play("Idle_Front", 0, 0f);
    }

    /// <summary>True while the animator is in (or blending into) an attack state.</summary>
    public bool IsAttacking =>
        _animator != null &&
        (_animator.GetCurrentAnimatorStateInfo(0).IsTag("Attack") ||
         (_animator.IsInTransition(0) && _animator.GetNextAnimatorStateInfo(0).IsTag("Attack")));

    /// <summary>
    /// No-op. Facing is now driven by the velocity blend tree (VelocityX/Y/Z), so explicit
    /// orientation is no longer needed. Kept to satisfy <see cref="IPlayerVisual"/>; the
    /// combat/interaction controllers still call it but the blend tree owns facing.
    /// </summary>
    public void FaceWorldDirection(Vector3 worldDir) { }

    private int _lastSector = 6; // default: front/south

    /// <summary>
    /// Switches the active direction view and flips the sprite based on the 8-direction
    /// facing sector. Only one view is active at a time; the rest are deactivated.
    /// Right/UR/DR flip their respective view by setting localScale.x = -1.
    /// </summary>
    private void UpdateDirectionView(Vector3 velocity)
    {
        Vector2 dir = new Vector2(velocity.x, velocity.z);
        if (dir.sqrMagnitude >= _faceDeadzone * _faceDeadzone)
        {
            // 0=E 1=NE 2=N 3=NW 4=W 5=SW 6=S 7=SE  (atan2: x=right, z=up/away)
            float ang = Mathf.Atan2(dir.y, dir.x) * Mathf.Rad2Deg;
            _lastSector = ((Mathf.RoundToInt(ang / 45f) % 8) + 8) % 8;
        }

        // Deactivate all views
        SetViewActive(_viewFront, false);
        SetViewActive(_viewBack, false);
        SetViewActive(_viewSide, false);
        SetViewActive(_viewLeftBack, false);
        SetViewActive(_viewLeftDown, false);

        // Activate the correct view with appropriate flip
        switch (_lastSector)
        {
            case 0: ActivateView(_viewSide, flipX: true);  break;      // E  Right
            case 1: ActivateView(_viewLeftBack, flipX: true); break;    // NE UR
            case 2: ActivateView(_viewBack, flipX: false); break;       // N  Back
            case 3: ActivateView(_viewLeftBack, flipX: false); break;   // NW UL
            case 4: ActivateView(_viewSide, flipX: false); break;       // W  Left
            case 5: ActivateView(_viewLeftDown, flipX: false); break;   // SW DL
            case 6: ActivateView(_viewFront, flipX: false); break;      // S  Front
            case 7: ActivateView(_viewLeftDown, flipX: true); break;     // SE DR
        }
    }

    private static void SetViewActive(GameObject view, bool active)
    {
        if (view != null) view.SetActive(active);
    }

    private static void ActivateView(GameObject view, bool flipX)
    {
        if (view == null) return;
        view.SetActive(true);
        var s = view.transform.localScale;
        s.x = flipX ? -1f : 1f;
        view.transform.localScale = s;
    }

    // ── Petal tracking ──────────────────────────────────────────────────────────

    /// <summary>
    /// Keeps the petal reparented to the active view's Head/PetalPivot so it tracks
    /// the correct anchor point per direction pose. Head bob carries it automatically.
    /// Procedural bounce/lean temporarily disabled — petal just tracks with the body.
    /// </summary>
    private void UpdatePetal()
    {
        if (_petal == null) return;
        var head = FindActiveHead();
        if (head == null) return;

        var pivot = head.Find("PetalPivot");
        if (pivot == null) return;

        if (_petal.parent != pivot)
        {
            _petal.SetParent(pivot, false);
            _petal.localPosition = Vector3.zero;
        }

        _petal.localRotation = Quaternion.identity;
    }

    // ── Head bob procedural animation ──────────────────────────────────────────

    private Vector3 _headBaseLocalPos;

    /// <summary>
    /// Applies a figure-8 bob to the Head of the active view. Head IS the body —
    /// all limb pivots, petal pivot, and the head sprite are children of Head, so
    /// this bob carries everything together automatically.
    /// </summary>
    private void UpdateHeadBob(float speed)
    {
        var head = FindActiveHead();
        if (head == null) return;

        // Cache base position once (direction views all use the same local pos)
        if (_headBaseLocalPos == default)
            _headBaseLocalPos = head.localPosition;

        float t = Time.time * _headBobSpeed;
        float speedFactor = Mathf.Clamp01(speed);

        // Figure-8: Y bounces twice per cycle, X sways once
        float y = Mathf.Sin(t * 2f) * _headBobHeight * speedFactor;
        float x = Mathf.Cos(t) * _headBobSway * speedFactor;
        float zTilt = Mathf.Sin(t) * _headBobTiltDeg * speedFactor;

        head.localPosition = _headBaseLocalPos + new Vector3(x, y, 0f);
        head.localRotation = Quaternion.Euler(0f, 0f, zTilt);
    }

    private Transform FindActiveHead()
    {
        if (_viewFront != null && _viewFront.activeSelf) return _viewFront.transform.Find("Head");
        if (_viewBack != null && _viewBack.activeSelf) return _viewBack.transform.Find("Head");
        if (_viewSide != null && _viewSide.activeSelf) return _viewSide.transform.Find("Head");
        if (_viewLeftBack != null && _viewLeftBack.activeSelf) return _viewLeftBack.transform.Find("Head");
        if (_viewLeftDown != null && _viewLeftDown.activeSelf) return _viewLeftDown.transform.Find("Head");
        return null;
    }

    // ── Limb walk cycle procedural animation ───────────────────────────────────

    /// <summary>
    /// Walk cycle for feet and arms via pivot transforms under Head. Left/right feet alternate
    /// (180° out of phase). Arms swing opposite to their same-side foot. Rotation axis depends
    /// on facing: Front/Back use X-axis (swing into screen), Side/Diagonal use Z-axis.
    /// Head IS the body — pivots are its children so they inherit head bob automatically.
    /// </summary>
    private void UpdateLimbs(float speed)
    {
        var head = FindActiveHead();
        if (head == null) return;

        float t = Time.time * _limbCycleSpeed;
        float sf = Mathf.Clamp01(speed);

        // Front/Back/Left_Down → X-axis (swing into screen); Side/Left_Back → Z-axis (swing sideways)
        bool useXAxis = (_viewFront != null && _viewFront.activeSelf) ||
                         (_viewBack != null && _viewBack.activeSelf) ||
                         (_viewLeftDown != null && _viewLeftDown.activeSelf);

        // Phase for left foot (also drives right arm — opposite limb)
        float leftPhase  = Mathf.Sin(t);
        // Phase for right foot (also drives left arm — opposite limb)
        float rightPhase = Mathf.Sin(t + Mathf.PI); // 180° offset

        foreach (Transform pivot in head)
        {
            string n = pivot.name;
            // Petal is driven by UpdatePetal — skip here
            if (n == "PetalPivot") continue;

            if (n == "LeftLegPivot")
            {
                float footTilt = -leftPhase * _footTiltDeg * sf;
                pivot.localRotation = useXAxis
                    ? Quaternion.Euler(footTilt, 0f, 0f)
                    : Quaternion.Euler(0f, 0f, footTilt);
            }
            else if (n == "RightLegPivot")
            {
                float footTilt = -rightPhase * _footTiltDeg * sf;
                pivot.localRotation = useXAxis
                    ? Quaternion.Euler(footTilt, 0f, 0f)
                    : Quaternion.Euler(0f, 0f, footTilt);
            }
            else if (n == "RightArmPivot")
            {
                // Right arm swings with left foot (same phase)
                float armTilt = leftPhase * _armTiltDeg * sf;
                pivot.localRotation = useXAxis
                    ? Quaternion.Euler(armTilt, 0f, 0f)
                    : Quaternion.Euler(0f, 0f, armTilt);
            }
            else if (n == "LeftArmPivot")
            {
                // Left arm swings with right foot (same phase)
                float armTilt = rightPhase * _armTiltDeg * sf;
                pivot.localRotation = useXAxis
                    ? Quaternion.Euler(armTilt, 0f, 0f)
                    : Quaternion.Euler(0f, 0f, armTilt);
            }
        }
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        _animator = this.GetComponent<Animator>();
        if (_sprite == null && _visualRoot != null) _sprite = _visualRoot.GetComponentInChildren<SpriteRenderer>();
        if (_camera == null) _camera = Camera.main;

        if (_visualRoot != null)
        {
            _visualRoot.localScale = Vector3.one * _visualScale;

            // Auto-find direction views by name if not assigned
            if (_viewFront == null) _viewFront = _visualRoot.Find("Front")?.gameObject;
            if (_viewBack == null) _viewBack = _visualRoot.Find("Back")?.gameObject;
            if (_viewSide == null) _viewSide = _visualRoot.Find("Side")?.gameObject;
            if (_viewLeftBack == null) _viewLeftBack = _visualRoot.Find("Left_Back")?.gameObject;
            if (_viewLeftDown == null) _viewLeftDown = _visualRoot.Find("Left_Down")?.gameObject;
            if (_petal == null) _petal = _visualRoot.Find("petal");
        }

        CacheAttackClipFrames();
    }

    /// <summary>
    /// Record each attack clip's last-frame index (length × frameRate) so the windup can scrub to
    /// exact frames. Clip names come from FlynnAnimationSetup: Flynn_attack_01..04 → tool index 1..4.
    /// </summary>
    private void CacheAttackClipFrames()
    {
        _attackLastFrame.Clear();
        if (_animator == null || _animator.runtimeAnimatorController == null) return;

        foreach (AnimationClip clip in _animator.runtimeAnimatorController.animationClips)
        {
            if (clip == null) continue;
            int idx = clip.name switch
            {
                "Flynn_attack_01" => 1,
                "Flynn_attack_02" => 2,
                "Flynn_attack_03" => 3,
                "Flynn_attack_04" => 4,
                _                 => 0,
            };
            if (idx == 0) continue;
            _attackLastFrame[idx] = Mathf.Max(1f, clip.length * clip.frameRate);
        }
    }

    private void LateUpdate()
    {
        if (_camera == null || _visualRoot == null) return;
        //_visualRoot.rotation = _camera.transform.rotation;
        //_visualRoot.localScale = Vector3.one * _visualScale;
    }

    private void Update()
    {
        // Locomotion is selected by a velocity blend tree: feed the Rigidbody velocity
        // (VelocityX/Y/Z), plus Speed (XZ magnitude) and IsGrounded for the idle/run/air split.
        Vector3 velocity = _controller.MoveInput; // use input for more responsive facing in the blend tree; the Rigidbody velocity feeds the actual speed parameter

        // The blend tree's (0,0) cell is the front/Down pose, so a raw zero input snaps the
        // facing back to front on release. Hold the last pressed XZ direction instead, so the
        // idle pose keeps facing wherever Flynn was last heading. Speed is still the real
        // magnitude, so this only steers the facing cell — it never fakes movement.
        Vector2 xz = new Vector2(velocity.x, velocity.z);
        if (xz.sqrMagnitude >= _faceDeadzone * _faceDeadzone) _lastFacingXZ = xz.normalized;
        Vector2 facingFeed = xz.sqrMagnitude >= _faceDeadzone * _faceDeadzone ? xz : _lastFacingXZ;

        _animator.SetFloat(xVelocityHash, facingFeed.x);
        _animator.SetFloat(yVelocityHash, velocity.y);
        _animator.SetFloat(zVelocityHash, facingFeed.y);
        _animator.SetFloat(SpeedHash, xz.magnitude);
        _animator.SetBool(IsGroundedHash, _controller.IsGrounded);

        // Direction view switching driven from the facing sector (no longer via animation curves).
        UpdateDirectionView(new Vector3(facingFeed.x, velocity.y, facingFeed.y));

        // Petal tracking (reparents to active view's PetalPivot).
        UpdatePetal();

        // Procedural head bob (figure-8 + tilt). Head IS the body — pivots inherit this.
        UpdateHeadBob(xz.magnitude);

        // Limb walk cycle — stubbed while focusing on body.
        // UpdateLimbs(xz.magnitude);

        // While swinging, the swing phase owns animator.speed (freeze on windup, scaled on
        // release) — skip the locomotion playback-speed reset.
        if (_swingPhase == SwingPhase.Charging)
        {
            _animator.speed = 0f;
            return;
        }
        if (_swingPhase == SwingPhase.Releasing)
        {
            _animator.speed = _attackSpeed;
            // Play settles a frame after ReleaseSwing; wait until we see the attack state
            // begin, then hand back to locomotion once it has exited.
            if (IsAttacking) _releaseSeen = true;
            else if (_releaseSeen) _swingPhase = SwingPhase.None;
            return;
        }

        // Blend tree plays at native rate; a prior swing may have left animator.speed scaled.
        _animator.speed = 1f;
    }
}

